const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();
if (input) {
  const n = parseInt(input, 10);
  const lines = [];

  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      row.push(Math.min(i, j, n - 1 - i, n - 1 - j) + 1);
    }
    lines.push(row.join(' '));
  }

  process.stdout.write(lines.join('\n') + '\n');
}
